        private static List<Instruction> ParseGates(string script,int n)
        {
            if(script.Length>12000)throw new ArgumentException("Gate script exceeds12000characters.");string[] commands=script.Split(';');if(commands.Length>256)throw new ArgumentException("Bounded gate script supports<=256instructions.");List<Instruction> result=new List<Instruction>();foreach(string raw in commands){string text=raw.Trim();if(text.Length==0)continue;string[] w=Regex.Split(text,@"\s+");string name=Alias(w[0]);Dictionary<string,object> spec=null;foreach(Dictionary<string,object> s in TrancheRegister.SupportedGates)if((string)s["name"]==name)spec=s;if(spec==null)throw new ArgumentException("Unsupported gate "+name+".");int ac=(int)spec["angleCount"],tc=(int)spec["targetCount"];bool all=w.Length==ac+2&&w[w.Length-1].Equals("all",StringComparison.OrdinalIgnoreCase);if(all&&!(bool)spec["local"])throw new ArgumentException("all applies only to local gates.");if(!all&&w.Length!=1+ac+tc)throw new ArgumentException("Wrong operands/angles for "+name+".");double[] angles=new double[ac];for(int a=0;a<ac;a++)angles[a]=Real(w[1+a]);Gate(name,angles);if(all){for(int q=0;q<n;q++)result.Add(new Instruction{Name=name,Angles=angles,Qubits=new int[]{q},Text=text});}else{int[] q=new int[tc];HashSet<int> seen=new HashSet<int>();for(int k=0;k<tc;k++){q[k]=Int(w[1+ac+k],0,n-1);if(!seen.Add(q[k]))throw new ArgumentException("Gate operands must be distinct.");}result.Add(new Instruction{Name=name,Angles=angles,Qubits=q,Text=text});}}return result;
        }
        private static Complex[,] Embed(Complex[,] local,int[] qs,int n){if(n<1||n>4)throw new ArgumentException("Explicit matrices support1..4qubits.");int d=1<<n,ld=1<<qs.Length;Complex[,] result=new Complex[d,d];int mask=0;foreach(int q in qs)mask|=1<<q;for(int x=0;x<d;x++){int lx=0;for(int k=0;k<qs.Length;k++)if((x&(1<<qs[k]))!=0)lx|=1<<k;for(int ly=0;ly<ld;ly++){int y=x&~mask;for(int k=0;k<qs.Length;k++)if((ly&(1<<k))!=0)y|=1<<qs[k];result[y,x]=local[ly,lx];}}return result;}
        private static Complex[,] CircuitMatrix(List<Instruction> instructions,int n){Complex[,] u=Id(1<<n);foreach(Instruction g in instructions)u=Mul(Embed(Gate(g.Name,g.Angles),g.Qubits,n),u);return u;}
        private static double UnitInterval(Dictionary<string,string> f,string key){double p=Real(Req(f,key));if(p<0||p>1)throw new ArgumentException(key+" must be in0..1.");return p;}
        private static Complex[] Qubit(string text){Complex[] v=Vec(text);SpinDoctorCalculators.RequirePure(v);if(v.Length!=2)throw new ArgumentException("A qubit requires exactly two normalized amplitudes.");return v;}
        private static Complex[,] Channel(Complex[,] rho,int n,int target,string channel,Dictionary<string,string> f)
        {
            List<Complex[,]> kraus=new List<Complex[,]>();if(channel=="bit-flip"||channel=="phase-flip"){double p=UnitInterval(f,"p");Complex[,] e0=Id(2),e1=Gate(channel=="bit-flip"?"x":"z",new double[0]);for(int i=0;i<2;i++)for(int j=0;j<2;j++){e0[i,j]*=Math.Sqrt(1-p);e1[i,j]*=Math.Sqrt(p);}kraus.Add(e0);kraus.Add(e1);}
            else if(channel=="depolarizing"){Choice(f,"convention","mix-with-I-over-2");double p=UnitInterval(f,"p");foreach(string name in new string[]{"i","x","y","z"}){Complex[,] e=Gate(name,new double[0]);double scale=Math.Sqrt(name=="i"?1-3*p/4:p/4);for(int i=0;i<2;i++)for(int j=0;j<2;j++)e[i,j]*=scale;kraus.Add(e);}}
            else if(channel=="amplitude-damping"){double gamma=UnitInterval(f,"gamma");kraus.Add(new Complex[,]{{1,0},{0,Math.Sqrt(1-gamma)}});kraus.Add(new Complex[,]{{0,Math.Sqrt(gamma)},{0,0}});}
            else if(channel=="dephasing"){Choice(f,"convention","offdiagonal-times-one-minus-lambda");double lambda=UnitInterval(f,"lambda");Complex[,] e0=Id(2),e1=Gate("z",new double[0]);for(int i=0;i<2;i++)for(int j=0;j<2;j++){e0[i,j]*=Math.Sqrt(1-lambda/2);e1[i,j]*=Math.Sqrt(lambda/2);}kraus.Add(e0);kraus.Add(e1);}else throw new ArgumentException("Unsupported named channel.");
            Complex[,] output=new Complex[1<<n,1<<n];foreach(Complex[,] e in kraus){Complex[,] full=Embed(e,new int[]{target},n);Complex[,] term=Mul(Mul(full,rho),Dag(full));for(int i=0;i<output.GetLength(0);i++)for(int j=0;j<output.GetLength(1);j++)output[i,j]+=term[i,j];}SpinDoctorCalculators.RequireDensity(output);return output;
        }
        private Dictionary<string,object> Noise(string action,Dictionary<string,string> f)
        {
