                string channel=Req(f,"channel").ToLowerInvariant(),parameter=channel=="amplitude-damping"?"gamma":channel=="dephasing"?"lambda":"p";string permitted=(action=="apply"?"state rho":"n input gates targets independent")+" channel "+parameter;if(channel=="depolarizing"||channel=="dephasing")permitted+=" convention";Fields(f,permitted);Complex[,] rho;int n=1,gateCount=0;int[] targets;
