        private Dictionary<string,object> Qec(string action,string sub,Dictionary<string,string> f)
        {
            if(action=="repetition3"||action=="phase-repetition3"){
                bool phase=action=="phase-repetition3";if(sub=="syndrome-table"){Fields(f,"errors stabilizers");if(phase)throw new ArgumentException("The supplied syndrome-table command uses the bit repetition code.");string[] st=SpinDoctorCalculators.SplitList(Req(f,"stabilizers"));if(st.Length!=2||SpinDoctorCalculators.Unquote(st[0])!="Z0 Z1"||SpinDoctorCalculators.Unquote(st[1])!="Z1 Z2")throw new ArgumentException("repetition3 syndrome table uses stabilizers Z0 Z1 and Z1 Z2.");string[] tableErrors=SpinDoctorCalculators.SplitList(Req(f,"errors"));if(tableErrors.Length<1||tableErrors.Length>8)throw new ArgumentException("Use1..8 explicit tableErrors.");object[] rows=new object[tableErrors.Length];for(int i=0;i<tableErrors.Length;i++){int tableMask=ErrorMask(new string[]{SpinDoctorCalculators.Unquote(tableErrors[i])},false);int[] syn=Syndrome(tableMask);rows[i]=D("error",SpinDoctorCalculators.Unquote(tableErrors[i]),"syndromeBits",syn,"stabilizerEigenvalues",new int[]{syn[0]==0?1:-1,syn[1]==0?1:-1},"recovery",Recovery(syn)<0?"I":"X"+Recovery(syn));}return D("rows",rows,"scope","Exact deterministic syndrome calculation for specified Pauli tableErrors; no syndrome shots sampled.");}
                if(sub!="encode"&&sub!="simulate")throw new ArgumentException("Use encode, simulate, or syndrome-table.");Fields(f,sub=="encode"?"state":"state error errors recover");Complex[] logical=Qubit(Req(f,"state"));Complex[] encoded=new Complex[8];encoded[0]=logical[0];encoded[7]=logical[1];Complex[,] hhh=SpinDoctorCalculators.Tensor(Gate("h",new double[0]),SpinDoctorCalculators.Tensor(Gate("h",new double[0]),Gate("h",new double[0])));if(phase)encoded=SpinDoctorCalculators.MatrixVector(hhh,encoded);if(sub=="encode")return D("encodedAmplitudes",V(encoded),"logicalAmplitudes",V(logical),"code",phase?"three-qubit phase repetition":"three-qubit bit repetition","scope","Actual8-component ideal encoding calculation; this code protects only its declared error class.");if(f.ContainsKey("error")==f.ContainsKey("errors"))throw new ArgumentException("Supply exactly one error or errors list.");string[] errors=f.ContainsKey("error")?new string[]{f["error"]}:SpinDoctorCalculators.SplitList(f["errors"]);if(errors.Length<1||errors.Length>32)throw new ArgumentException("Use1..32 specified Pauli error factors.");int mask=ErrorMask(errors,phase);int[] syndrome=Syndrome(mask);int recovery=Recovery(syndrome);bool recover=SpinDoctorCalculators.Boolean(Opt(f,"recover","true"));int correctedMask=mask^(recover&&recovery>=0?1<<recovery:0);Complex[] corrupted=ApplyMask(encoded,mask,phase),corrected=recover&&recovery>=0?ApplyMask(corrupted,1<<recovery,phase):corrupted;Complex[] decoded=phase?SpinDoctorCalculators.MatrixVector(hhh,corrected):corrected;Complex[] decodedLogical={decoded[0],decoded[7]};double codeMass=decodedLogical[0].Magnitude*decodedLogical[0].Magnitude+decodedLogical[1].Magnitude*decodedLogical[1].Magnitude;Complex overlap=SpinDoctorCalculators.Overlap(encoded,corrected);return D("encodedAmplitudes",V(encoded),"erroredAmplitudes",V(corrupted),"correctedAmplitudes",V(corrected),"syndromeBits",syndrome,"recovery",recover&&recovery>=0?(phase?"Z":"X")+recovery:"I","recover