        private static int ErrorMask(string[] errors,bool phase){int mask=0;foreach(string raw in errors){string e=SpinDoctorCalculators.Unquote(raw).ToUpperInvariant();if(e=="I")continue;if(!Regex.IsMatch(e,phase?@"^Z[012]$":@"^X[012]$"))throw new ArgumentException("This code demonstration accepts only I and "+(phase?"Z":"X")+"0..2 factors.");mask^=1<<(e[1]-'0');}return mask;}
        private static int[] Syndrome(int mask){return new int[]{((mask>>0)^(mask>>1))&1,((mask>>1)^(mask>>2))&1};}
        private static int Recovery(int[] s){if(s[0]==1&&s[1]==0)return 0;if(s[0]==1&&s[1]==1)return 1;if(s[0]==0&&s[1]==1)return 2;return -1;}
        private static Complex[] ApplyMask(Complex[] input,int mask,bool phase){Complex[] result=new Complex[input.Length];for(int id=0;id<input.Length;id++){if(phase){int parity=0;for(int q=0;q<3;q++)if((mask&(1<<q))!=0&&(id&(1<<q))!=0)parity^=1;result[id]=parity==0?input[id]:-input[id];}else result[id^mask]=input[id];}return result;}
        private sealed class Pauli {public Dictionary<int,char> Terms=new Dictionary<int,char>();public Complex Phase=Complex.One;public int Highest;public Pauli Clone(){return new Pauli{Terms=new Dictionary<int,char>(Terms),Phase=Phase,Highest=Highest};}public ulong Binary(){ulong bits=0;foreach(KeyValuePair<int,char> t in Terms){if(t.Value=='X'||t.Value=='Y')bits|=1UL<<t.Key;if(t.Value=='Z'||t.Value=='Y')bits|=1UL<<(29+t.Key);}return bits;}}
        private static Pauli ReadPauli(string text){Complex phase=Complex.One;text=text.Trim();if(text.StartsWith("-")){phase=-1;text=text.Substring(1).Trim();}else if(text.StartsWith("+"))text=text.Substring(1).Trim();Dictionary<int,char> terms=SpinDoctorCalculators.ParsePauli(text,29);Pauli p=new Pauli{Terms=terms,Phase=phase};foreach(int q in terms.Keys)p.Highest=Math.Max(p.Highest,q);return p;}
        private static Pauli MultiplyPauli(Pauli a,Pauli b){Pauli result=a.Clone();result.Phase*=b.Phase;foreach(KeyValuePair<int,char> t in b.Terms){char prior;result.Terms.TryGetValue(t.Key,out prior);if(prior=='\0'||prior=='I'){result.Terms[t.Key]=t.Value;continue;}if(t.Value=='I')continue;if(prior==t.Value){result.Terms.Remove(t.Key);continue;}char c=(prior!='X'&&t.Value!='X')?'X':(prior!='Y'&&t.Value!='Y')?'Y':'Z';bool positive=(prior=='X'&&t.Value=='Y')||(prior=='Y'&&t.Value=='Z')||(prior=='Z'&&t.Value=='X');result.Terms[t.Key]=c;result.Phase*=positive?Complex.ImaginaryOne:-Complex.ImaginaryOne;}result.Highest=Math.Max(a.Highest,b.Highest);return result;}

        private Dictionary<string,object> Compile(string action,Dictionary<string,string> f)
        {
            if(action=="synthesize")throw new InvalidOperationException("Needs backend: validated Clifford+T synthesis and requested operator-norm error bound are not installed.");
            if(action=="universality"){Fields(f,"set semantics");Choice(f,"semantics","approximate");string[] names=SpinDoctorCalculators.SplitList(Req(f,"set"));HashSet<string> set=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(string name in names)set.Add(SpinDoctorCalculators.Unquote(name));if(set.Count!=3||!set.Contains("h")||!set.Contains("t")||!set.Contains("cx"))throw new ArgumentException("This reference entry is for {H,T,CX}.");return D("resultKind","theory","backend","documented-theory","approximatelyUniversal",true,"explanation","Repeated H,T and CX generate approximately universal qubit circuits; one circuit containing a T gate alone is neither universal computation nor a proof of speedup. No synthesized sequence or hardware error guarantee is returned.","references",new string[]{"https://arxiv.org/abs/quant-ph/0403025"});}
            if(action=="identity"){Fields(f,"left right n equivalence");int n=Int(Req(f,"n"),1,4);string equivalence=Opt(f,"equivalence","exact");if(equivalence!="exact"&&equivalence!="global-phase")throw new ArgumentException("equivalence is exact or global-phase.");List<Instruction> left=ParseGates(Req(f,"left"),n),right=ParseGates(Req(f,"right"),n);Complex[,] a=CircuitMatrix(left,n),b=CircuitMatrix(right,n);Complex phase;double error=SpinDoctorCalculators.MatrixDifference(a,b,equivalence=="global-phase",out phase);return D("equivalent",error<=1e-12,"maximumElementError",error,"tolerance",1e-12,"equivalence",equivalence,"phaseMultiplier",SpinDoctorCalculators.ComplexJson(phase),"leftGateApplications",left.Count,"rightGateApplications",right.Count,"leftMatrix",M(a),"rightMatrix",M(b),"scope","Full small-register matrices composed chronologically; no gate sequence committed to selected circuit.");}
            if(action=="simplify"){Fields(f,"n gates preserve-global-phase");Choice(f,"preserve-global-phase","true");int n=Int(Req(f,"n"),1,29);List<Instruction> input=ParseGates(Req(f,"gates"),n),stack=new List<Instruction>();int removed=0;foreach(Instruction current in input){bool cancel=false;if(stack.Count>0){Instruction previous=stack[stack.Count-1];bool operands=previous.Qubits.Length==current.Qubits.Length;for(int q=0;operands&&q<previous.Qubits.Length;q++)operands&=previous.Qubits[q]==current.Qubits[q];if(operands){Complex[,] product=Mul(Gate(current.Name,current.Angles),Gate(previous.Name,previous.Angles));Complex phase;cancel=SpinDoctorCalculators.MatrixDifference(product,Id(product.GetLength(0)),false,out phase)<=1e-12;}}if(cancel){stack.RemoveAt(stack.Count-1);removed+=2;}else stack.Add(current);}object[] output=new object[stack.Count];for(int i=0;i<output.Length;i++)output[i]=GateRecord(stack[i]);return D("originalGateApplications",input.Count,"remainingGateApplications",stack.Count,"removedGateApplications",removed,"gates",output,"preserveGlobalPhase",true,"scope","Only adjacent same-operand exact inverse pairs canceled at1e-12 element tolerance; no commuting or approximate rewrite guessed.");}
            if(action=="count"||action=="depth"||action=="classify"){Fields(f,action=="count"?"n gates counting":action=="depth"?"n gates connectivity scheduling":"n gates input");int n=Int(Req(f,"n"),1,29);List<Instruction> gates=ParseGates(Req(f,"gates"),n);if(action=="count"){Choice(f,"counting","logical");int t=0,two=0,three=0;Dictionary<string,int> names=new Dictionary<string,int>();foreach(Instruction g in gates){if(g.Name=="t"||g.Name=="tdg")t++;if(g.Qubits.Length==2)two++;if(g.Qubits.Length==3)three++;if(!names.ContainsKey(g.Name))names[g.Name]=0;names[g.Name]++;}return D("logicalGateApplications",gates.Count,"TCount",t,"twoQubitCount",two,"threeQubitCount",three,"perGate",names,"resultKind","resource-estimate","scope","Logical expanded gate count; not simulator arithmetic or hardware duration.");}if(action=="depth"){Choice(f,"connectivity","all-to-all");Choice(f,"scheduling","earliest-dependencies");int[] ends=new int[n];int depth=0;object[] schedule=new object[gates.Count];for(int i=0;i<gates.Count;i++){int layer=1;foreach(int q in gates[i].Qubits)layer=Math.Max(layer,ends[q]+1);foreach(int q in gates[i].Qubits)ends[q]=layer;depth=Math.Max(depth,layer);schedule[i]=D("gate",GateRecord(gates[i]),"layer",layer);}return D("idealLogicalDepth",depth,"schedule",schedule,"connectivity","all-to-all","resultKind","resource-estimate","scope","Unit-duration logical gates, no crosstalk/routing/measurement/control latency. Disjoint operands may share a layer.");}Choice(f,"input","computational-basis");bool clifford=true;List<string> non=new List<string>();foreach(Instruction g in gates)if(!IsClifford(Gate(g.Name,g.Angles),g.Qubits.Length)){clifford=false;non.Add(g.Name);}return D("classification",clifford?"Clifford-compatible":"contains-non-Clifford","cliffordAtTolerance",clifford,"tolerance",1e-10,"nonCliffordInstructions",non.ToArray(),"recommendedBackend",clifford?"phase-aware stabilizer tableau if installed":"selected coherent statevector/factors","installedExecutionBackend","selected coherent statevector/factors","tableauBackendInstalled",false,"scope","Checked conjugation of local Pauli generators. Classification is not an executed circuit or a computational-advantage proof.");}
            throw new ArgumentException("Unsupported q.compile action.");
        }
        private static Dictionary<string,object> GateRecord(Instruction g){return D("name",g.Name,"angles",g.Angles,"qubits",g.Qubits);}
        private static bool IsClifford(Complex[,] u,int n){int count=1<<(2*n);Complex[,] ud=Dag(u);for(int q=0;q<n;q++)foreach(char axis in new char[]{'X','Z'}){Complex[,] test=Mul(Mul(u,SpinDoctorCalculators.PauliMatrix(axis+q.ToString(Inv),n)),ud);bool found=false;for(int code=0;code<count&&!found;code++){List<string> parts=new List<string>();for(int k=0;k<n;k++){int a=(code>>(2*k))&3;if(a>0)parts.Add((a==1?"X":a==2?"Y":"Z")+k.ToString(Inv));}Complex[,] p=SpinDoctorCalculators.PauliMatrix(String.Join(" ",parts),n);Complex phase;double err=SpinDoctorCalculators.MatrixDifference(test,p,true,out phase);if(err<=1e-10&&Math.Abs(phase.Imaginary)<=1e-10&&Math.Abs(Math.Abs(phase.Real)-1)<=1e-10)found=true;}if(!found)return false;}return true;}
        private Dictionary<string,object> Algorithm(string action,Dictionary<string,string> f)
        {
            if(action!="phase-estimation")throw new ArgumentException("Unsupported q.algorithm action.");Fields(f,"counting-qubits unitary eigenstate power-map inverse-qft");Choice(f,"power-map","qj-controls-U^(2^j)");Choice(f,"inverse-qft","include-final-swaps");int m=Int(Req(f,"counting-qubits"),1,8),n=m+1;string[] unitary=Regex.Split(Req(f,"unitary").Trim(),@"\s+");if(unitary.Length!=3||Alias(unitary[0])!="p"||Int(unitary[2],m,m)!=m)throw new ArgumentException("This validated phase-estimation toy backend requires unitary='p ANGLE TARGET' with TARGET=counting-qubits.");double theta=Real(unitary[1]);if(Math.Abs(theta)>1e9)throw new ArgumentException("Phase-estimation base angle magnitude<=1e9.");Complex[] eigen=Qubit(Req(f,"eigenstate"));bool zero=Complex.Abs(eigen[1])<=1e-12,one=Complex.Abs(eigen[0])<=1e-12;if(!zero&&!one)throw new ArgumentException("The supplied vector must be a computational eigenstate of P; arbitrary eigenstate/unitary phase estimation needs another backend.");Complex[] state=new Complex[1<<n];state[0]=eigen[0];state[1<<m]=eigen[1];List<Instruction> gates=new List<Instruction>();for(int q=0;q<m;q++)gates.Add(new Instruction{Name="h",Angles=new double[0],Qubits=new int[]{q}});for(int q=0;q<m;q++)gates.Add(new Instruction{Name="cp",Angles=new double[]{theta*Math.Pow(2,q)},Qubits=new int[]{q,m}});List<Instruction> qft=new List<Instruction>();for(int q=m-1;q>=0;q--){qft.Add(new Instruction{Name="h",Angles=new double[0],Qubits=new int[]{q}});for(int lower=q-1;lower>=0;lower--)qft.Add(new Instruction{Name="cp",Angles=new double[]{Math.PI/Math.Pow(2,q-lower)},Qubits=new int[]{q,lower}});}for(int q=0;q<m/2;q++)qft.Add(new Instruction{Name="swap",Angles=new double[0],Qubits=new int[]{q,m-1-q}});for(int i=qft.Count-1;i>=0;i--){Instruction g=qft[i];double[] a=new double[g.Angles.Length];for(int j=0;j<a.Length;j++)a[j]=-g.Angles[j];gates.Add(new Instruction{Name=g.Name,Angles=a,Qubits=g.Qubits});}long writes=2,products=0;foreach(Instruction g in gates){Complex[,] gm=Gate(g.Name,g.Angles);long pw,pp;state=Apply(state,gm,g.Qubits,out pw,out pp);writes+=pw;products+=pp;}SpinDoctorCalculators.RequirePure(state);double[] probabilities=new double[1<<m];for(int x=0;x<state.Length;x++)probabilities[x&((1<<m)-1)]+=state[x].Magnitude*state[x].Magnitude;int likely=0;for(int x=1;x<probabilities.Length;x++)if(probabilities[x]>probabilities[likely])likely=x;double expectedPhase=one?theta/(2*Math.PI):0;expectedPhase-=Math.Floor(expectedPhase);return D("countingQubits",m,"targetQubit",m,"probabilities",probabilities,"mostLikelyOutcome",likely,"mostLikelyBitstring",SpinDoctorCalculators.Bits((ulong)likely,m),"mostLikelyPhase",(double)likely/(1<<m),"eigenphaseModuloOne",expectedPhase,"premeasurementAmplitudes",V(state),"simulatedGateApplications",gates.Count,"actualAmplitudeWrites",writes,"actualComplexMultiplications",products,"actualPreparedStateVectors",1,"sampledShots",0,"scope","Actual bounded coherent statevector evolution; no measurement draws. Counts are source-level simulator work, not physical quantum operations.","powerMap","qj controls U^(2^j)","qftConvention","Inverse positive-exponent QFT with final bit-reversal swaps; q0 least significant.");
        }
        private static Complex[] Apply(Complex[] state,Complex[,] gate,int[] qs,out long writes,out long products){int local=1<<qs.Length,mask=0;foreach(int q in qs)mask|=1<<q;Complex[] result=new Complex[state.Length];writes=state.Length;products=(long)state.Length*local;for(int y=0;y<result.Length;y++){int ly=0;for(int k=0;k<qs.Length;k++)if((y&(1<<qs[k]))!=0)ly|=1<<k;int baseId=y&~mask;Complex value=Complex.Zero;for(int lx=0;lx<local;lx++){int x=baseId;for(int k=0;k<qs.Length;k++)if((lx&(1<<k))!=0)x|=1<<qs[k];value+=gate[ly,lx]*state[x];}result[y]=value;}return result;}
